x-codeSamples.source:
curl --request POST \
  --url https://api.fish.audio/v1/agent/agents \
  --header 'Authorization: Bearer <token>' \
  --header 'Content-Type: application/json' \
  --data '{
    "name": "Receptionist",
    "description": "Handles inbound calls.",
    "config": {
      "prompt": {
        "system_prompt": "You are the receptionist for Fish Dental."
      },
      "voice": {
        "voice_id": "<voice-model-id>",
        "speaking_language": "en"
      }
    }
  }'

curl --request PATCH \
  --url https://api.fish.audio/v1/agent/agents/<agent-id>/config \
  --header 'Authorization: Bearer <token>' \
  --header 'Content-Type: application/json' \
  --data '{
    "prompt": {
      "system_prompt": "You are the receptionist for Fish Dental."
    },
    "webhooks": {
      "post_call": [
        {
          "url": "https://example.com/hooks/fish",
          "secret": "<signing-secret>"
        }
      ]
    }
  }'

curl --request POST \
  --url https://api.fish.audio/v1/agent/tools \
  --header 'Authorization: Bearer <token>' \
  --header 'Content-Type: application/json' \
  --data '{
    "name": "Book appointment",
    "description": "Creates an appointment in the scheduling system.",
    "method": "POST",
    "url": "https://api.example.com/appointments",
    "arguments": [
      {"name": "date", "description": "Appointment date, YYYY-MM-DD"}
    ],
    "body_template": "{\"date\": \"{{date}}\"}",
    "headers": [
      {"name": "Authorization", "value": "Bearer <api-token>", "kind": "authorization_bearer"}
    ]
  }'
